def ring_allreduce_s(size_gb, n, bw_gbs, alpha_us):
    bandwidth_term = 2 * (n - 1) / n * size_gb / bw_gbs
    latency_term = 2 * (n - 1) * alpha_us * 1e-6
    return bandwidth_term + latency_term


for n in (8, 64, 1024):
    print(n, round(ring_allreduce_s(14, n, 50, 5), 4), 's')
